.onePictrue {
  padding: 0 15px;

  .info {
    font-size: 12px;
    color: #BBBBBB;
  }

  .bnt {
    width: 100%;
    height: 36px;
    border-radius: 3px;
    opacity: 1;
    border: 1px solid #EEEEEE;
    color: #666666;
    font-size: 12px;
    text-align: center;
    line-height: 36px;
    margin-top: 20px;
    cursor: pointer;
  }

  .pictrues {
    width: 370px;
    height: 100%;
    margin-top: 20px;

    img {
      width: 100%;
      height: 100%;
    }

    .emptyBox {
      height: 164px;
      background: #F9F9F9;
      border-radius: 3px 3px 3px 3px;
      font-size: 12px;
      color: #BBBBBB;
      text-align: center;
      line-height: 164px;
    }
  }

  .uploadImg {
    display: flex;
    align-items: center;
    height: 96px;
    background: #F9F9F9;
    border-radius: 3px;
    width: 100%;
    margin-top: 20px;
    padding: 0 20px;

    .name {
      font-size: 12px;
      color: #999999;
      margin-right: 16px;
    }

    .picTxt {
      display: flex;
      align-items: center;

      .box {
        width: 64px;
        height: 64px;
        position: relative;
        background: url('../../assets/images/transparents.jpg') no-repeat;
        background-size: 100% 100%;
        border-radius: 3px;

        .upload-box {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 64px;
          height: 64px;
          background: #fff;
          border-radius: 4px;
          border: 1px solid #EEEEEE;

          .ivu-icon {
            color: #ccc;
          }
        }

        .pictrue {
          position: relative;
          width: 100%;
          height: 100%;

          .iconfont {
            position: absolute;
            right: -12px;
            top: -19px;
            font-size: 24px;
            color: #CCCCCC;
          }
        }

        img {
          width: 64px;
          border-radius: 3px;
		  max-height: 64px;
		  object-fit: cover;
        }
      }

      .tip {
        color: #BBBBBB;
        font-size: 12px;
        margin-left: 20px;
      }
    }
  }
}
